            (predictions[key] - predictions[("factual", 1.0)])
            - (r272_base[key] - r272_base[("factual", 1.0)]), axis=0
        ).round(5).tolist()
    r272_trials[ridge] = {"correction": correction, "summary": result}
    print("ridge", ridge, result)

